# -*- coding: utf-8 -*-
"""
build_exemplars_auto.py — 解构引擎：批量生成语法透视图数据

输入：data/lessons.json 的 jp_raw（带 ! 词界标记与 (かな) 注音，是权威读音来源）
输出：data/exemplars.json（合并保留原有手写条目）

引擎负责机械部分：分词、助词着色、词义标注、振假名、罗马音、
逐词中文直译行、零主语推理、SVG 箭头锚点。
认知心法（cognitive_note）逐句手写——这是教学质量的落点，不交给模板。

用法：python build_exemplars_auto.py [--lessons 1-4]
"""

import io
import json
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(HERE, 'content'))

import morphology as M  # noqa: E402

LESSONS_PATH = os.path.join(HERE, 'data', 'lessons.json')
EXEMPLARS_PATH = os.path.join(HERE, 'data', 'exemplars.json')

# 保留这些手写条目，不被引擎覆盖（视频原型与早期人工样例）
PRESERVE_IDS = {'screenshot_showcase'}

# ============================================================ 视频原型的中文化
# screenshot_showcase 是最早手写的"1:1 复刻 B站原片"样例，词注与直译行原本用英文。
# 引擎生成的新内容一律用中文词注——对中文学习者来说，英文词注本身就是一道额外的坎。
# 两套语言混在同一屏上更糟，所以把原型也统一成中文。
# "1:1 复刻"指的是视觉系统（Ø が 红框＋弧形箭头、彩色助词框、词下形态拆解、
# 逻辑小句直译行、悬停联动），不是词注语种。
SHOWCASE_GLOSS_ZH = {
    'chunk_kyou': ('今天', ''),
    'chunk_ame': ('雨', '（だ＝断定的简体形）'),
    'chunk_kasa': ('伞', ''),
    'chunk_motte': ('拿着', '（持つ 的て形）'),
    'chunk_iku': ('去／走', ''),
}

SHOWCASE_LITERAL_ZH = [
    [{'text': '因为', 'color': 'cyan', 'underline': True, 'target_chunk': 'chunk_ame'},
     {'text': '至于', 'color': 'blue', 'underline': True, 'target_chunk': 'chunk_kyou'},
     {'text': '今天', 'color': 'normal', 'underline': False},
     {'text': '（天气）', 'color': 'red', 'underline': True, 'target_chunk': 'zero_ga'},
     {'text': '是雨', 'color': 'normal', 'underline': False}],
    [{'text': '（我）', 'color': 'red', 'underline': True, 'target_chunk': 'zero_ga'},
     {'text': '把', 'color': 'orange', 'underline': True, 'target_chunk': 'chunk_kasa'},
     {'text': '伞', 'color': 'normal', 'underline': False},
     {'text': '拿着', 'color': 'normal', 'underline': False},
     {'text': '然后去', 'color': 'normal', 'underline': False}],
]


def localize_showcase(ex):
    """把视频原型的英文词注与直译行改成中文。返回新 dict，不改动入参。"""
    out = json.loads(json.dumps(ex, ensure_ascii=False))
    for c in out.get('chunks', []):
        zh = SHOWCASE_GLOSS_ZH.get(c.get('id'))
        if zh:
            c['gloss_main'] = zh[0]
            c['gloss_sub'] = zh[1]
    if out.get('literal_structure'):
        out['literal_structure'] = [
            {'clause': i + 1, 'tokens': t} for i, t in enumerate(SHOWCASE_LITERAL_ZH)
        ]
    return out


# 第6课与第14课的两条早期手写样例。它们不在本轮覆盖范围（引擎尚未支持
