# literal 一律写成完整 token dict（含 color/underline/target_chunk），不再按位置
# 继承旧数据的颜色——继承会在增删 token 时把颜色错位地钉到别的词上。
# 助词直译词的位置严格照 LIT 表（は→前置「至于」、と→后置「和」、を→前置「把」、
# へ→前置「朝」），保证 legacy 与引擎生成用同一套规则。
