        '前一个动作是后一个动作的起点，所以「聞いてから 寝ます」＝先听后睡，不能颠倒。'
        '与单纯 て 的区别：て 只说「接着」（两个动作挨着），'
        'てから 明说「以…为起点」（有先后要求，常带「做完再」的语气）。'
