# ============================================================ 引擎主体

# 连体／并列助词：它们把两个词焊成一个成分，不能当词尾格助词处理。
#   の  连体（所属/属性）：駅の 外      → 车站的外面
#   と  并列（完全列举）：机と いす    → 桌子和椅子
#   や  并列（不完全列举）：机や いす  → 桌子和椅子等
#   な  な形容词的连体形（第9课起）：静かな 町 → 安静的 城市
#      —— な 本身不是格助词，它只把な形容词降级成修饰语；罗马音层不管它
#      （きれいな人形 仍写 kireina ningyou），这里只负责把短语合成一个成分。
LINKERS = {
    'の': {'join': '的', 'lit': '的'},
    'な': {'join': '的', 'lit': '的'},
    'と': {'join': '和', 'lit': '和'},
    'や': {'join': '和', 'lit': '和…等'},
}

# と／や 一身两职：并列（机といすが）vs 伴随（森さんと日本へ）。
# 并列的标志是整串最后落在主语/话题/宾语标记上（が/は/も/を），
# 或干脆直接接谓语；伴随的标志是后接 へ/で/から/まで 这类 adjunct 标记。
# 只在并列签名出现时合并，伴随一律保持拆开。
COORD_FINAL_OK = {'が', 'は', 'も', 'を'}


def _na_attributive(seg):
    """
    な形容词的连体形（静かな／きれいな）→ 词干＋连体助词 な。

    为什么要单独合成一个 な：罗马音层不能把 な 当助词剥出去
    （教材的读法是 kireina ningyou 一个词，C14 的回归用例钉着这个结果），
    但透视图里「静かな 町」必须是一个成分——否则 な 会像 の 那样被拍平，
    学习者会以为「静かな」是个独立的词。所以只在这一层补出 な。
    查不到词表就原样返回（让 gloss 走「な形容词（连体形）」那条路）。
    """
    if seg.get('kind') == 'punct' or seg.get('particle') or seg.get('predicate') \
            or seg.get('final') or seg.get('conj'):
        return seg
    body = seg.get('body') or ''
    if not body.endswith('な'):
        return seg
    dic, _form = M.adj_form(body)
    if not dic:
        return seg
    out = dict(seg)
    out['body'] = body[:-1]
    if (out.get('body_read') or '').endswith('な'):
        out['body_read'] = out['body_read'][:-1]
    out['particle'] = 'な'
    return out


def merge_attributive(segments):
    """
    把「连体/并列助词悬空段」并入后一个名词段，还原嵌套或并列的名词短语。

    の／な／と／や 都要求后接名词：段尾挂着它们而没有谓语，说明这个段不完整
    （「駅の」不是个东西，「駅の外」才是；「静かな」也不是，「静かな町」才是）。
    旧引擎按全角空格硬切，把嵌套/并列结构拍平成两个平级块，
    等于宣称 の/と 是前一个词的格助词——这是语法错误，不是显示偏好。

    合并条件刻意收紧：
      * 该段 particle 属于 LINKERS，且没有谓语、没有终助词
        （「スミスさんのです」带谓语 です，の 是名词化，不合并）
      * 后一段必须有名词词体（所以句尾的「静かな」不会被硬并）
      * と／や 还需整串收尾呈现并列签名（见 COORD_FINAL_OK），
        否则按伴随处理、保持拆开（第6课「森さんと日本へ」属此类）
    链式（AのBのC / AとBとC）通过循环自然折叠。
    第 15 课起又补了两类同样的"整体关系"：
      * 连体词＋名词（この＋コンピュータ）——连体词不能独立充当句子成分；
      * 谓语＋形式名词（弾く＋こと／来る＋前に／終わった＋後で／食べた＋ほう）——
        形式名词不承担实义，只把前面的谓语收拢成一个整体。
    链式（AのBのC / AとBとC）通过循环自然折叠。
    """
    segments = _fold_rentai(list(segments))
    # 给な形容词补出连体助词 な（只在后面确实跟着名词时补，见 _na_attributive）
    for k, seg in enumerate(segments):
        nxt = segments[k + 1] if k + 1 < len(segments) else None
        if nxt is None or nxt['kind'] == 'punct' or not (nxt.get('body') or ''):
            continue
        segments[k] = _na_attributive(seg)

    out = []
    i = 0
    n = len(segments)
    while i < n:
        seg = segments[i]
        if seg['kind'] == 'punct':
            out.append(seg)
            i += 1
            continue
        comps = [seg]
        while comps[-1].get('particle') in LINKERS \
                and not comps[-1].get('predicate') \
                and not comps[-1].get('final'):
            j = i + len(comps)
            nxt = segments[j] if j < n else None
            if nxt is None or nxt['kind'] == 'punct' or not (nxt.get('body') or ''):
                break
            comps.append(nxt)

        if len(comps) > 1 and not _is_coordination(comps):
            comps = [comps[0]]   # 伴随读法：不合并，退回单段
        if len(comps) > 1:
            out.append(compose_phrase(comps))
            i += len(comps)
            continue

        # 谓语＋形式名词（第20／21课）：弾く＋こと／来る＋前に／終わった＋後で／食べた＋ほうが
        nxt = segments[i + 1] if i + 1 < n else None
        if nxt is not None and nxt['kind'] != 'punct' \
                and form_noun_key(nxt) \
                and _is_predicate_like(seg) and not seg.get('particle') \
                and not seg.get('final'):
            out.append(compose_modifier_phrase(seg, nxt))
            i += 2
            continue
        out.append(seg)
        i += 1
    return out


def _is_coordination(comps):
    """と／や 串起来的串，收尾必须是并列签名才合并；の／な 串无条件合并。"""
    linkers = [c.get('particle') for c in comps[:-1]]
    if all(l in ('の', 'な') for l in linkers):
        return True
    # 并列标记重复出现时，收尾会再挂一个同样的 と／や：
    #   ビールと 日本酒と，どちらが 好きですか——这是并列短语的标准写法，必须合并。
    #   （と 在这里不是前一个词的格助词，而是并列短语自己的收尾标记。）
    last_early = comps[-1]
    if last_early.get('particle') in ('と', 'や') \
            and all(l == last_early.get('particle') for l in linkers):
        return True
    last = comps[-1]
    # 并列的标志：收尾落在主语／话题／宾语标记上（机といすが、コーラとケーキを）
    if last.get('particle') in COORD_FINAL_OK:
        return True
    # 收尾直接是谓语（コーラとケーキです）也是并列；
    # 但「友達と 帰りました」的收尾是动词（帰ります），那是伴随，不能合并。
    # 词表里 帰ります 是动词，这就是 §8.2 需要的自动判据。
    if last.get('predicate') and not last.get('particle') \
            and not M.verb_masu_form(last.get('body') or ''):
        return True
    return False


def compose_phrase(comps):
    """把多个被 の/と/や 串起来的段折叠成一个名词短语段。"""
    head = comps[-1]
    glosses = []
    for c in comps:
        g = M.gloss_of(c.get('body') or '') or {}
        # 形式名词（の／つもり／はず／ところ／ほど…）在中文里必须与前接谓语连读，
        # 不能退回它当独立名词时的词义（玄関のところ 不是"门口的 地方"）。
        fn_zh = FORM_NOUN_ZH.get(form_noun_key(c) or '') if c is head else ''
        # 已经折过一次的成分（连体词＋名词）要保留它自己的中文，别退回日文词面
        glosses.append(fn_zh or c.get('phrase_gloss') or g.get('zh') or c.get('body') or '')
    joined = glosses[0]
    for k, c in enumerate(comps[:-1]):
        joined += LINKERS[c['particle']]['join'] + glosses[k + 1]
    merged = dict(head)
    merged['phrase'] = True
    merged['components'] = comps
    merged['body'] = ''.join(
        c['body'] + (comps[k + 1] and c['particle'] or '') for k, c in enumerate(comps[:-1])
    ) + comps[-1]['body']
    merged['body_read'] = ''.join(
        c['body_read'] + c['particle'] for c in comps[:-1]
    ) + comps[-1]['body_read']
    merged['phrase_gloss'] = joined
    if form_noun_key(head):
        merged['form_noun'] = True
    # 段的字面要跟着一起拼：生成深层结构提示（Ø が 的 tooltip）时用它才不会漏掉修饰语
    merged['surf'] = ''.join(c.get('surf') or '' for c in comps)
    # 词级粒度要保住连接助词，也要把黏在词尾的助词剥出来：
    #   机の上 → ['つくえ', 'の', 'うえ'] → 块内罗马音 tsukue no ue
    # 词级粒度只按 ! 断词，助词常常黏在词尾（つくえの），所以这里手动拆一次。
    words = []
    for k, c in enumerate(comps):
        lk = c.get('particle') or ''
        ws = list(c.get('words') or [])
        if lk and ws and ws[-1].endswith(lk) and len(ws[-1]) > len(lk):
            ws[-1] = ws[-1][:-len(lk)]
        words.extend(ws)
        if k < len(comps) - 1 and lk:
            words.append(lk)
    merged['words'] = [w for w in words if w]
    return merged


# ============================================================ 修饰关系：连体词＋名词 / 谓语＋形式名词
def _is_rentai(seg):
    """连体词段（この／その／あの／どんな…）。"""
    return (not seg.get('particle') and not seg.get('predicate')
            and (seg.get('body') or '') in RENTAI_ZH)


def _body_pos(seg):
    """词体的词性标签（词表给的中文，如「な形容词」「动词・Ⅰ类（基本形）」）。"""
    return (M.gloss_of(seg.get('body') or '') or {}).get('pos') or ''


def _is_predicate_like(seg):
    """这一段是不是谓语性的词（动词／形容词的活用形）。

    形式名词 こと／ほう／前／後 只能接在谓语性成分后面：
    「弾く＋こと」「食べた＋ほう」「終わった＋後で」——两段合起来才是一个成分。
    """
    if seg.get('predicate') or seg.get('predicate_inner') or seg.get('inflection'):
        return True
    # 词性标签在活用形上写的是形态（「（基本形）」「（た形）」「（たり：列举）」…），
    # 所以不能只认"动词／形容词"开头的标签——反过来，只有名词性的词才排除。
    # 形式名词前只允许出现谓语性成分（名词要带 の 才能修饰名词）。
    pos = _body_pos(seg)
    return not pos.startswith(('名词', '专有名词', '代词', '数量词', '连体词', '人名'))


def compose_modifier_phrase(mod, head):
    """把「连体词＋名词」或「谓语＋形式名词」折成一个成分块。

    合并不是拍平：修饰语与被修饰语的关系是"整体进入句子"的关系，
    分开摆等于宣称「この」/「来る」是能独立充当成分的东西，那是语法错误。
    """
    out = dict(head)
    comps = [mod] + list(head.get('components') or [head])
    out['phrase'] = True
    out['components'] = comps
    out['body'] = (mod.get('body') or '') + (head.get('body') or '')
    out['body_read'] = (mod.get('body_read') or '') + (head.get('body_read') or '')
    out['surf'] = (mod.get('surf') or '') + (head.get('surf') or '')
    mod_zh = (RENTAI_ZH.get(mod.get('body') or '')
              or (M.gloss_of(mod.get('body') or '') or {}).get('zh')
              or mod.get('body') or '')
    fn_key = form_noun_key(head)
    if fn_key:
        # 形式名词：こと＝这件事、まえ＝之前……中文里必须和前面的谓语连读
        out['form_noun'] = True
        out['phrase_gloss'] = mod_zh + FORM_NOUN_ZH[fn_key]
    else:
        out['phrase_gloss'] = mod_zh + (
            head.get('phrase_gloss')
            or (M.gloss_of(head.get('body') or '') or {}).get('zh')
            or head.get('body') or '')
    hw = list(head.get('words') or [])
    lp = head.get('particle') or ''
    if lp and hw and hw[-1].endswith(lp) and len(hw[-1]) > len(lp):
        hw[-1] = hw[-1][:-len(lp)]
    out['words'] = [w for w in list(mod.get('words') or []) + hw if w]
    # 折过的成分要自带渲染单元与直译 token：外层短语再折一次时（この＋コンピュータの＋操作），
    # 内层短语的 parts 只覆盖它自己的词体，不能靠 body 长度去猜振假名。
    out['jp_units'] = (list(mod.get('jp_units') or ruby_units_for(mod, mod.get('body') or ''))
                       + list(head.get('jp_units') or ruby_units_for(head, head.get('body') or '')))
    out['lit_tokens'] = ([{'text': mod_zh, 'color': 'normal', 'underline': False}]
                         + list(head.get('lit_tokens') or [
                             {'text': head.get('phrase_gloss') or (M.gloss_of(head.get('body') or '')
                                                                   or {}).get('zh') or head.get('body') or '',
                              'color': 'normal', 'underline': False}]))
    return out


def form_noun_key(seg):
    """形式名词的规范键。

    词面可能是汉字、读音是假名（前＝まえ／後＝あと），两边都要认，
    否则「来る前に」「終わった後で」不会合并——这两句的 前／後 并不是
    "前面／后面"那个独立名词，它们是时间从句的形式名词。
    """
    body = seg.get('body') or ''
    if body in FORM_NOUN_HEADS:
        return body
    read = seg.get('body_read') or ''
    return read if read in FORM_NOUN_HEADS else ''


def _fold_rentai(segments):
    """把连体词并进它修饰的那个成分（この＋コンピュータの操作 → 一个块）。"""
    out = []
    pending = None
    for seg in segments:
        if pending is None and seg['kind'] != 'punct' and _is_rentai(seg):
            pending = seg
            continue
        if pending is not None and seg['kind'] != 'punct' and (seg.get('body') or ''):
            out.append(compose_modifier_phrase(pending, seg))
            pending = None
            continue
        if pending is not None:
            out.append(pending)      # 后面没有名词可修饰：原样放回
            pending = None
        out.append(seg)
    if pending is not None:
        out.append(pending)
    return out


def seg_surface(seg):
    """段在句面上的原文（词体＋助词＋活用尾＋谓语＋接续／终助词）。

    拼深层结构提示时不能直接用 seg['surf']：活用形要靠活用尾才拼得回来
    （読ん＋で → 読んで），否则提示里会出现半个词。
    """
    if seg['kind'] == 'punct':
        return seg['surf']
    return ((seg.get('body') or '') + (seg.get('particle') or '')
            + (seg.get('predicate_inner') or '') + (seg.get('predicate') or '')
            + (seg.get('conj') or '') + (seg.get('final') or ''))


def inner_info(form, body_pos=''):
    """活用尾的呈现信息：引擎认识就先用引擎的，否则用本文件补的表。

    な形容词的 で／に 与动词て形的 で 同形，靠词体的词性区分——
    つまり 簡単で（并列中顿）≠ 読んで（て形）。
    """
    if form in NA_INNER_FORMS and 'な形容词' in (body_pos or ''):
        return NA_INNER_FORMS[form]
    info = M.predicate_info(form)
    if info and info[0]:
        return info
    return INNER_FORMS.get(form) or (form, '（活用尾）', 'green', form)


def form_lit_token(sub):
    """按 gloss_sub 里的形态说明给出直译行的形态标注词；没有就返回 None。"""
    for key, tok in FORM_LIT_TOKENS:
        if key in (sub or ''):
            return tok
    return None


def ruby_units_for(seg, body):
    """词体对应的振假名单元序列（不含助词）。"""
    return [{'type': 'ruby', 'kanji': p['kanji'], 'kana': p['kana']}
            for p in ruby_parts_for(seg, body)]


def body_romaji(seg):
    """词体部分的罗马音，保留 ! 给出的词界空格。"""
    body_read = seg.get('body_read') or ''
    if not body_read:
        return ''
    words = seg.get('words') or []
    if len(words) <= 1:
        return M._spaced_reading(body_read)
    out = []
    remain = body_read
    for w in words:
        if not remain:
            break
        if remain.startswith(w):
            out.append(M._spaced_reading(w))
            remain = remain[len(w):]
        else:
            out.append(M._spaced_reading(remain))
            remain = ''
    return ' '.join(x for x in out if x)


def ruby_parts_for(seg, body):
    """按词体长度截取 parts，拼出 <ruby> 所需的 kanji/kana 序列。"""
    if not body:
        return []
    parts = []
    remain = len(body)
    for p in seg.get('parts', []):
        if remain <= 0:
            break
        s = p['surf']
        if len(s) <= remain:
            parts.append({'kanji': s, 'kana': p['read'] if p.get('ann') else ''})
            remain -= len(s)
        else:
            parts.append({'kanji': s[:remain], 'kana': ''})
            remain = 0
    return parts


def build_chunks(segments):
    """
    把分析后的语块段编译成 diagram.js 需要的 chunks 数组。
    每段最多产出三个 chunk：词体（带助词框）、谓语、终助词。
    """
    chunks = []
    n = 0

    def nid():
        nonlocal n
        n += 1
        return 'c%d' % n

    prev_te = False          # 上一段是不是动词て形（供「〜て ください」「てから」判断）
    prev_body = ''           # 上一段词体（判断 て形＋います 是「正在进行」还是「结果状态」）
    prev_sub = ''            # 上一段词体的形态说明（判断 ください 前面是 て形 还是 ないで）
    for seg in segments:
        if seg['kind'] == 'punct':
            continue
        seg_te = seg.get('predicate_inner') == 'て'

        # --- 词体 + 助词 ---
        body = seg.get('body') or ''
        if body:
            pname = seg.get('particle') or ''
            # 助词 'か' 走到这里一定是「并列・不定」用法（句尾疑问的 か 已被 final 剥走），
            # 所以用 PARTICLES_NONFINAL 的那套名称／颜色／说明。
            meta = M.PARTICLES_NONFINAL.get(pname) or M.PARTICLES.get(pname, {})
            chunk = {
                'id': nid(),
                'text': body,
                'romaji': body_romaji(seg),
                'particle': seg.get('particle') or '',
                'particle_color': meta.get('color', 'none'),
                'particle_name': meta.get('name', ''),
                'particle_desc': meta.get('desc', ''),
                'underline_color': meta.get('color', 'none'),
                'underline_span': 'full',
                'src_seg': seg['surf'],
                'kind': 'body',
            }

            if seg.get('phrase'):
                # 名词短语（駅の 外 / 机の 上 / JC企画の 社員）：
                # の 渲染成块内连接框，不再冒充词尾格助词；
                # gloss 是整个短语的含义，直译行也按短语整体出 token。
                comps = seg['components']
                units = []
                lit = []
                for ci, c in enumerate(comps):
                    units.extend(c.get('jp_units') or ruby_units_for(c, c['body']))
                    cg = M.gloss_of(c['body']) or {}
                    czh = c.get('phrase_gloss') or cg.get('zh') or c['body']
                    if seg.get('form_noun') and ci == len(comps) - 1:
                        # 形式名词的中文必须与前一段连读（こと＝这件事，不是"事情"这个名词）
                        czh = FORM_NOUN_ZH.get(form_noun_key(c) or '') or czh
                    lit.append({'text': czh, 'color': 'normal', 'underline': False})
                    # 修饰语与被修饰语之间没有连接助词时（この＋名詞／来る＋前に），
                    # 不画连接框：它们本来就是同一个成分，不是两个词被助词连着。
                    lk = c['particle'] if ci < len(comps) - 1 else ''
                    if lk:
                        nmeta = M.PARTICLES[lk]
                        units.append({'type': 'box', 'particle': lk,
                                      'color': nmeta['color'],
                                      'name': nmeta['name'], 'desc': nmeta['desc']})
                        lit.append({'text': LINKERS[lk]['lit'], 'color': nmeta['color'],
                                    'underline': True, 'target_chunk': chunk['id']})
                chunk['jp_units'] = units
                chunk['lit_tokens'] = lit
                # 成分数组必须落进 chunk：审计器 C3 靠它逐个查短语内部成分的词义
                # （前端只用 jp_units/lit_tokens，所以这里一度漏了，C3 的短语检查因此空转）。
                chunk['components'] = comps
                chunk['gloss_main'] = seg['phrase_gloss']
                chunk['gloss_sub'] = '形式名词短语' if seg.get('form_noun') else '名词短语'
                chunk['phrase'] = True
                if seg.get('form_noun'):
                    # 形式名词短语的形态说明：告诉初学者这是哪种句型。
                    # 词义（gloss_main）保持"吃（这一边）"这种连读形式，不覆盖。
                    fn_key = form_noun_key(seg) or ''
                    if fn_key == 'ほう':
                        chunk['gloss_sub'] = '形式名词：～た／～ない ほうがいい（哪一边）'
                    elif fn_key in ('まえ', 'あと'):
                        chunk['gloss_sub'] = '形式名词：时间从句（～る前に／～た後で）'
            else:
                g = M.gloss_of(body, prefer_verb=bool(seg.get('inflection'))) or {}
                chunk['gloss_main'] = g.get('zh') or body
                chunk['gloss_sub'] = g.get('pos') or ''
                # 敬语 お／ご＋ます语干（第47课 お帰りになりました）：这个语干在这里是动词，
                # 不是同形的名词（帰り＝"回程"）。查同形的 ます形 词条拿动词词义。
                if chunks and ('敬语' in (chunks[-1].get('gloss_sub') or '')
                               or '敬语' in (chunks[-1].get('gloss_main') or '')):
                    vg = M.gloss_of(body + 'ます') or {}
                    if vg.get('zh') and not vg.get('partial'):
                        chunk['gloss_main'] = vg['zh']
                        chunk['gloss_sub'] = '动词・ます形（敬语 お／ご～ 的语干）'
                bridge = GLOSS_BRIDGE.get(body)
                if bridge:
                    # 少数固定说法：分词器识别出形态之前先在编译侧兜底词义与形态说明
                    # （只补词义，不动分词边界）。必须放在 gloss_sub 赋值之后，否则会被覆盖。
                    chunk['gloss_main'], chunk['gloss_sub'] = bridge
                elif not g.get('zh') or g.get('partial') or g.get('zh') == body:
                    # 「谓语＋形式名词」被引擎判成段内切片、段体没拆开时（フリーズすること），
                    # 词义按"谓语＋形式名词"连读给，形态说明写明它是个形式名词短语。
                    for fn in sorted(FORM_NOUN_ZH, key=len, reverse=True):
                        if body.endswith(fn) and len(body) > len(fn) + 1:
                            hg = M.gloss_of(body[:-len(fn)]) or {}
                            if hg.get('zh') and not hg.get('partial'):
                                chunk['gloss_main'] = hg['zh'] + FORM_NOUN_ZH[fn]
                                chunk['gloss_sub'] = '形式名词（～%s）' % fn
                            break
                if body == 'どう' and (seg.get('particle') or '') == 'か':
                    # かどうか（第23课）：这颗 か 长在 どうか 里面，不是"并列・不定"那颗，
                    # 词义要按「是否」给，否则初学者会把它读成"怎样 或"。
                    chunk['gloss_main'] = '是否'
                    chunk['gloss_sub'] = '（かどうか：是不是）'
                rp = ruby_parts_for(seg, body)
                if rp and any(p['kana'] for p in rp):
                    chunk['ruby_parts'] = rp
                elif rp and len(rp) == 1:
                    chunk['ruby'] = rp[0]['kana']
            chunks.append(chunk)

        # --- 内层谓语尾：い形容词活用（楽し＋かった）与第15课起的た形（食べ＋た）---
        # 顺序必须是先内层后外层：楽し → かった → です，读者才能顺着看见活用怎么长出来。
        inner = seg.get('predicate_inner')
        if inner:
            body_pos = (M.gloss_of(seg.get('body') or '',
                                   prefer_verb=bool(seg.get('inflection'))) or {}).get('pos') or ''
            zh, note, color, _lit = inner_info(inner, body_pos)
            chunks.append({
                'id': nid(),
                'text': inner,
                'romaji': M._spaced_reading(inner),
                'gloss_main': zh,
                'gloss_sub': note,
                'particle': '',
                'particle_color': 'none',
                'particle_name': '',
                'particle_desc': '',
                'underline_color': color,
                'underline_span': 'full',
                'kind': 'predicate',
                'inflection': bool(seg.get('inner_inflection')),
                'src_seg': seg['surf'],
            })

        # --- 谓语 ---
        pred = seg.get('predicate')
        if pred:
            zh, note, color, _lit = M.predicate_info(pred)
            if pred == 'ください':
                # て形＋ください＝请对方做某事（不是「给我」）；ないで＋ください＝请勿
                psub = prev_sub or ''
                if 'ないで' in psub:
                    zh, note = '请（不要…）', '补助动词・命令形（ないで＋ください＝请勿）'
                elif seg_te or prev_te or 'て形' in psub \
                        or (prev_body or '').endswith(('て', 'で')):
                    zh, note = '请（做）', '补助动词・命令形（て形＋ください＝请对方做）'
            elif pred in ('います', 'いる') and (seg_te or prev_te or 'て形' in (prev_sub or '')):
                # て形＋います：动词的语义类别决定它是「正在进行」还是「结果状态」
                #   読んでいます＝正在看的动作；持っています＝拿着（有）这个状态。
                if (prev_body or '') in _TE_STATIVE_STEMS:
                    zh, note = '着（结果状态）', '补助动词：て いる＝动作完成后留下的状态'
                else:
                    zh, note = '正在（做）', '补助动词：て いる＝动作正在进行'
            chunks.append({
                'id': nid(),
                'text': pred,
                'romaji': M._spaced_reading(pred),
                'gloss_main': zh,
                'gloss_sub': note,
                'particle': '',
                'particle_color': 'none',
                'particle_name': '',
                'particle_desc': '',
                'underline_color': color,
                'underline_span': 'full',
                'kind': 'predicate',
                'inflection': bool(seg.get('inflection')),
                'src_seg': seg['surf'],
            })

        # --- 接续助词：挂在谓语之后的 から／が（好きですから／有料ですが）---
        conj = seg.get('conj')
        if conj:
            cmeta = M.PARTICLES.get(conj, {})
            chunks.append({
                'id': nid(),
                'text': conj,
                'romaji': M._spaced_reading(conj),
                'gloss_main': ('之后' if (conj == 'から' and (seg_te or prev_te))
                               else (CONJ_LIT.get(conj) or cmeta.get('gloss', conj))),
                'gloss_sub': ('接续助词（てから＝之后）' if (conj == 'から' and (seg_te or prev_te))
                              else '接续助词（挂在谓语之后）'),
                'particle': '',
                'particle_color': 'none',
                'particle_name': '',
                'particle_desc': cmeta.get('desc', ''),
                'underline_color': cmeta.get('color', 'cyan'),
                'underline_span': 'full',
                'kind': 'conj',
                'src_seg': seg['surf'],
            })

        # --- 终助词 ---
        fin = seg.get('final')
        if fin:
            fmeta = M.PARTICLES.get(fin, {})
            chunks.append({
                'id': nid(),
                'text': fin,
                'romaji': M._spaced_reading(fin),
                'gloss_main': FINAL_LIT.get(fin, fin),
                'gloss_sub': fmeta.get('name', '终助词'),
                'particle': '',
                'particle_color': 'none',
                'particle_name': '',
                'particle_desc': fmeta.get('desc', ''),
                'underline_color': fmeta.get('color', 'slate'),
                'underline_span': 'full',
                'kind': 'final',
                'src_seg': seg['surf'],
            })
        prev_te = seg_te          # 只认动词て形：供「〜て ください」「てから」判断
        prev_body = body
        prev_sub = (M.gloss_of(body, prefer_verb=bool(seg.get('inflection'))) or {}).get('pos') or ''

    return chunks


def build_literal(segments, chunks):
    """
    生成逐词中文直译行。严格保持日语语序，
    助词的直译词按 LIT 表前置或后置，颜色与透视图助词框一致以便悬停联动。
    """
    ci = iter(chunks)
    clauses = []
    cur = []
    # 同句谓语（词体读法＋活用尾巴）——用来判断 を 是宾语还是起点／经过
    verbs = [(s.get('body_read') or '') + (s.get('predicate') or '')
             for s in segments if s.get('predicate')]

    def tok(text, color='normal', underline=False, target=None):
        t = {'text': text, 'color': color, 'underline': underline}
        if target:
            t['target_chunk'] = target
        return t

    for seg in segments:
        if seg['kind'] == 'punct':
            if seg['surf'] in ('，', '、'):
                clauses.append(cur)
                cur = []
            continue

        body = seg.get('body') or ''
        part = seg.get('particle')
        inner = seg.get('predicate_inner')
        pred = seg.get('predicate')
        conj = seg.get('conj')
        fin = seg.get('final')

        # chunk 的消费顺序必须与 build_chunks 的产出顺序一致：
        # 词体 → 内层谓词尾（かった／ない）→ 外层谓词尾（です…）→ 接续助词 → 终助词
        body_chunk = next(ci, None) if body else None
        inner_chunk = next(ci, None) if inner else None
        pred_chunk = next(ci, None) if pred else None
        conj_chunk = next(ci, None) if conj else None
        fin_chunk = next(ci, None) if fin else None

        lit = LIT.get(part or '', {'pre': '', 'post': ''})
        if body == 'どう' and part == 'か':
            # かどうか：这里的 か 长在 どうか 里面，不是"并列・不定"那颗 か，
            # 直译行不能再出一个"或"（否则读成"怎样 或"）。
            lit = {'pre': '', 'post': ''}
        if part == 'で':
            # 場所で（在）与 手段で（用）：直译词看名词本身是不是"地方"
            lit = {'pre': _de_literal(body), 'post': ''}
        elif part == 'を':
            # を 是宾语还是起点／经过，看同句谓语（家を 出ます → 从；公園を 散歩します → 在）
            lit = {'pre': _wo_literal(verbs), 'post': ''}
        elif part == 'に':
            # 数量词＋に 是计数基准（一週間に 二回＝每）；动词ます形＋に 是移动目的（出しに 行きます）
            if M.counter_gloss(body):
                lit = {'pre': '每', 'post': ''}
            elif M.verb_masu_form(body) or M.suru_verb_base(body):
                lit = {'pre': '去', 'post': ''}
        if seg.get('form_noun'):
            # 形式名词短语里的 に／で／が 已被短语吸收（来る前に → 来之前），
            # 直译行不再另出一个助词词，否则会读成「在 来之前」。
            lit = {'pre': '', 'post': ''}
        color_meta = M.PARTICLES_NONFINAL.get(part or '') or M.PARTICLES.get(part or '', {})
        color = color_meta.get('color', 'normal')
        g = M.gloss_of(body, prefer_verb=bool(seg.get('inflection'))) if body else None
        # 直译行用词块的最终词义（编译侧的兜底覆盖过的那些才算数，例如敬语语干）
        body_zh = (body_chunk or {}).get('gloss_main') or (g or {}).get('zh') or body

        if part and lit['pre']:
            cur.append(tok(lit['pre'], color, True, body_chunk['id'] if body_chunk else None))

        if body_chunk:
            if body_chunk.get('lit_tokens'):
                # 名词短语：直译行按「修饰语 的 中心语」出多个 token，
                # 保持短语作为一个整体，不再被拍平成两个平级词
                cur.extend(body_chunk['lit_tokens'])
            else:
                # 助词无直译词时（如 が），把颜色直接打在名词本体上，保住联动
                body_color = color if (part and not lit['pre'] and not lit['post']) else 'normal'
                cur.append(tok(body_zh, body_color, bool(part and not lit['pre'] and not lit['post']),
                               body_chunk['id'] if part else None))

        if body_chunk and not inner:
            # 整块保留的活用形（たり／ないで／来ると）在直译行里补一个形态标注，
            # 否则直译行只剩一个词义，语法标记全丢了。
            ftok = form_lit_token(body_chunk.get('gloss_sub'))
            if ftok:
                cur.append(tok(ftok, 'green', True, body_chunk['id']))

        if part and lit['post']:
            cur.append(tok(lit['post'], color, True, body_chunk['id'] if body_chunk else None))

        if inner_chunk:
            # 内层谓词尾（い形容词活用）：楽し＋かった／熱く＋ない。
            # 直译行用「（过去）／不」这类短词义，跟外层谓词保持一致。
            # 活用尾的短词义：引擎的活用尾表 + 本文件补的（た形／たり／な形容词 で）。
            cur.append(tok(inner_info(inner, (g or {}).get('pos') or '')[3],
                           'green', True, inner_chunk['id']))

        if pred_chunk:
            # 直译行用短词义（PREDICATES 第4项）。「有・在（人/动物）」这种
            # 完整词义放在词下注释框里合适，塞进逐词直译行会把整行撑爆。
            psub = pred_chunk.get('gloss_sub') or ''
            if psub.startswith('补助动词：て いる'):
                plit = '正在' if '正在进行' in psub else '着'
            else:
                pinfo = M.predicate_info(pred)
                plit = pinfo[3] if pinfo else ('（简体）' if pred == 'だ' else pred)
            cur.append(tok(plit, 'green', True, pred_chunk['id']))

        if conj_chunk:
            # てから：から 挂在て形后面，直译是「之后」；单纯谓语的 から 才是「因为」
            ctext = '之后' if (conj == 'から' and inner == 'て') else CONJ_LIT.get(conj, conj)
            cur.append(tok(ctext, 'cyan', True, conj_chunk['id']))

        if fin_chunk:
            cur.append(tok(FINAL_LIT.get(fin, fin), 'slate', True, fin_chunk['id']))

    clauses.append(cur)
    return [{'clause': i + 1, 'tokens': c} for i, c in enumerate(clauses) if c]


def infer_zero_subject(segments, chunks, clean):
    """
    推理深层主语（零代词）。五种情形：
      1. 出现显式 が → 主语已在句面上，不显示 Ø が（存在句属此类）
      2. と 引用＋思う（第24课）→ は 标的话题属于**从句**，主句主语是说话人
         （「李さんは 来ると 思います」＝我想小李会来，不是小李在想）
      3. 出现 は／も 话题 → Ø が 与话题同指：は 把 が 吸收了
      4. 话题是时间名词、谓语却不是名词谓语（昨日は とても 忙しかった／
         明日は 残業しなくても いいです）→ 时间名词只是状语，真正的主语（我）仍在后台
      5. 两者都没有 → 依谓语类型推断（疑问→听话人，劝诱→双方，其他→说话人）
    """
    has_ga = any(s.get('particle') == 'が' for s in segments if s['kind'] != 'punct')
    if has_ga:
        return None

    if _quote_marker(segments) and any(
            (s.get('body') or '') in QUOTATIVE_SPEAKER_STEMS
            for s in segments if s['kind'] != 'punct'):
        target = next((c for c in reversed(chunks) if c.get('kind') == 'predicate'), None)
        if target:
            return {
                'symbol': 'Ø',
                'particle': 'が',
                'tooltip': ZERO_TOOLTIP_IMPLICIT.format(subject='说话人（我）'),
                'targets': [{'id': target['id'], 'label': '说话人（我）'}],
            }

    topic_seg = next((s for s in segments
                      if s['kind'] != 'punct' and s.get('particle') in ('は', 'も')), None)
    if topic_seg and not _time_topic_adverbial(segments, topic_seg):
        topic_chunk = next((c for c in chunks if c.get('src_seg') == topic_seg['surf']), None)
        if not topic_chunk:
            return None
        g = M.gloss_of(topic_seg.get('body') or '') or {}
        topic_zh = topic_seg.get('phrase_gloss') or g.get('zh') or topic_seg.get('body') or ''
        # 提示里要写「X が …」的完整深层结构：把话题段去掉，用其余段的字面拼出来。
        # 不能用 clean——analyze_sentence 的 clean 不带语块空格（全角空格被当分隔符吃掉了）；
        # 也不能直接用 surf——活用形要靠活用尾才拼得回来（読ん＋で → 読んで）。
        rest = ''.join(seg_surface(s) for s in segments
                       if s['kind'] != 'punct' and s is not topic_seg)
        return {
            'symbol': 'Ø',
            'particle': 'が',
            'tooltip': ZERO_TOOLTIP_ABSORED.format(topic=topic_seg.get('body', ''), rest=rest),
            'targets': [{'id': topic_chunk['id'], 'label': '%s（＝话题，は 吸收了 が）' % topic_zh}],
        }
    pred_seg = next((s for s in segments
                     if s['kind'] != 'punct' and s.get('predicate')), None)
    if pred_seg is None:
        # 形容词句的谓语长在活用尾上（忙しかった＝忙し＋かった），也要能推断主语
        pred_seg = next((s for s in segments
                         if s['kind'] != 'punct' and s.get('predicate_inner')), None)
    if pred_seg is None:
        return None
    pred = pred_seg.get('predicate') or pred_seg.get('predicate_inner') or ''
    is_question = bool(pred_seg.get('final')) or pred.endswith('か')
    has_particle = any(s.get('particle') for s in segments if s['kind'] != 'punct')
    if pred in ('です', 'でした') and not has_particle:
        # 时刻／状态句（今四時です／明日です）：深层"主语"是当前情况而不是人，
        # 硬标成"我"会教错，所以这里不显示 Ø が。
        return None
    if pred == 'ましょう':
        # ましょうか 是"我来……吧"（说话人），ましょう 是"咱们一起……吧"（双方）
        subject = '说话人（我）' if is_question else '我们（双方）'
    elif pred == 'ません':
        # ませんか 是劝诱（咱们一起……好吗），不是真在问对方做不做
        subject = '我们（双方）' if is_question else '说话人（我）'
    elif pred in ('ください', 'くださいませんか'):
        subject = '听话人（你）'
    elif is_question:
        subject = '听话人（你）'
    else:
        subject = '说话人（我）'
    # 箭头钉在句子主谓语上（最后一个谓语块），不能钉在活用尾或补助动词上
    target = next((c for c in reversed(chunks) if c.get('kind') == 'predicate'), None)
    if not target:
        return None
    return {
        'symbol': 'Ø',
        'particle': 'が',
        'tooltip': ZERO_TOOLTIP_IMPLICIT.format(subject=subject),
        'targets': [{'id': target['id'], 'label': subject}],
    }


def _is_nominal_predicate(segments):
    """句尾是不是「名词＋断定」的名词谓语（曇りだ／日曜日です）。"""
    segs = [s for s in segments if s['kind'] != 'punct']
    for k in range(len(segs) - 1, -1, -1):
        if (segs[k].get('predicate') or '') in ('です', 'だ', 'でした', 'だった',
                                                'ではありません', 'ではない'):
            for j in range(k - 1, -1, -1):
                if not (segs[j].get('body') or ''):
                    continue
                if segs[j].get('phrase'):
                    return True          # 形式名词短语／名词短语做谓语内容
                pos = (M.gloss_of(segs[j].get('body') or '') or {}).get('pos') or ''
                return pos.startswith('名词') or pos.startswith('专有名词')
            return False
    return False


def _quote_marker(segments):
    """句子里有没有 と 的引用标记（～と言う／～と思う 的 と）。

    词表把「来ると」标成「（基本形＋と：引用）」，这是引用句的可靠签名。
    """
    for s in segments:
        if s['kind'] == 'punct':
            continue
        pos = (M.gloss_of(s.get('body') or '') or {}).get('pos') or ''
        if 'と：引用' in pos:
            return True
    return False


def _time_topic_adverbial(segments, topic_seg):
    """时间名词做话题时，它究竟是主语还是状语？

    今日は 曇りだ → 名词谓语，话题就是主语（今天＝阴天）；
    昨日は とても 忙しかった／明日は 残業しなくても いいです → 谓语是形容词或动词，
    时间名词只交代时间，真正的主语（我）隐在后台——这时把 Ø が 钉在时间名词上会教错。
    """
    if (topic_seg.get('body') or '') not in TIME_TOPICS:
        return False
    return not _is_nominal_predicate(segments)


def _patched_raw(raw):
    """透视图与罗马音数据层必须用**同一份修订过的句面**（build_romaji.SOURCE_PATCHES）。
    否则教材注音错字（如第13课 一週間(いちしゅうかん)）会让两边算出不同的罗马音，
    C14 会直接报「透视图整句罗马音与数据层不一致」。"""
    try:
        import build_romaji as B
        return B.patch_raw(raw)[0]
    except Exception:
        return raw


def build_exemplar(lesson_num, sentence_id, b4, lesson_title):
    """为一句基本课文生成一条透视图数据。"""
    analysis = M.analyze_sentence(_patched_raw(b4['jp_raw']))
    # 先还原 の 串起来的嵌套名词短语，再做块级编译；
    # 否则「駅の／外に」会被切成两个平级块，把嵌套结构拍平。
    segments = merge_attributive(analysis['segments'])
    clean = analysis['clean']
    romaji = analysis['romaji']

    chunks = build_chunks(segments)
    literal = build_literal(segments, chunks)
    zero = infer_zero_subject(segments, chunks, clean)

    tag, title = SENTENCE_META.get(sentence_id, ('第%d课' % lesson_num, lesson_title))
    note = COGNITIVE_NOTES.get(sentence_id)
    if not note:
        raise SystemExit('缺少 %s 的认知心法（cognitive_note 必须手写，不自动生成）' % sentence_id)

    zh = (b4.get('zh') or '').lstrip('*').strip()

    ex = {
        'id': sentence_id,
        'lesson': lesson_num,
        'is_featured': False,
        'auto_generated': True,
        'tag': tag,
        'lesson_title': title,
        'sentence_raw': clean,
        'sentence_romaji': romaji,
        'source_id': b4.get('id'),
        'natural_translation': zh,
    }
    if zero:
        ex['zero_subject'] = zero
    ex['chunks'] = chunks
    ex['literal_structure'] = literal
    ex['cognitive_note'] = note
    return ex


# ============================================================ 课文：简单透视图
# 用户口径：课文（会话课文＋应用课文）的透视图只要 词块＋助词框＋振假名——
# 不要词义、不要逐词直译行、不要认知心法、不要零主语 Ø 标记。
# 所以这类条目既不走词表查义、也不生成 literal_structure/cognitive_note，
# 唯一硬指标是分词边界、助词归属、振假名与罗马音正确（由 audit_exemplars 的 C1/C2/C4/C5/C7 把关）。
SIMPLE_LESSONS = range(1, 49)


_CN_CHAR = re.compile(r'[\u4e00-\u9fff]')
_KANA = re.compile(r'[\u3040-\u30ff]')


def _is_non_japanese_chunk(c):
    """这个 chunk 是不是"教材夹进来的汉语"（连带它的汉语引号）？

    判据：词面里既没有假名，也没有振假名读法。
    日语汉字词一定带读法（中国→ちゅうごく、気→き），而 "再见" 与汉语引号 “ ” 没有——
    只按"有没有汉字"判断会把 中国／気 这类正常词一起误删。
    """
    text = c.get('text') or ''
    if _KANA.search(text):
        return False
    if c.get('ruby'):
        return False
    for p in c.get('ruby_parts') or []:
        if p.get('kana'):
            return False
    for u in c.get('jp_units') or []:
        if u.get('kana'):
            return False
    return True


def _strip_gloss(chunks):
    """简单图不带词义：删掉 gloss_* 与短语的 lit_tokens（它们只服务于词义与直译行）。"""
    out = []
    for c in chunks:
        c = dict(c)
        for k in ('gloss_main', 'gloss_sub', 'lit_tokens'):
            c.pop(k, None)
        if c.get('components'):
            c['components'] = _strip_gloss(c['components'])
        out.append(c)
    return out


def _clean_romaji(s):
    """与 build_romaji.clean_romaji 同源：去掉罗马音里的汉语原文与汉语引号。"""
    try:
        import build_romaji as BR
        return BR.clean_romaji(s or '')
    except Exception:
        return (s or '').strip()


def build_simple_exemplar(lesson_num, sentence_id, kind_label, source_id, item):
    """课文句子 → 简单透视图条目（词块＋助词框＋振假名）。

    整行都是汉语原文时返回 None——没有日语成分可拆，前端也就不该给它渲染按钮。
    """
    analysis = M.analyze_sentence(_patched_raw(item.get('jp_raw') or ''))
    segments = merge_attributive(analysis['segments'])
    chunks = [c for c in _strip_gloss(build_chunks(segments))
              if not _is_non_japanese_chunk(c)]
    if not chunks:
        return None
    return {
        'id': sentence_id,
        'lesson': lesson_num,
        'simple': True,
        'auto_generated': True,
        'kind_label': kind_label,
        'source_id': source_id,
        'sentence_raw': analysis['clean'],
        # 整句罗马音按数据层的同一条规则清洗：教材夹的汉语原文（“再见！”）不进罗马音行，
        # 否则那句罗马音会含非拉丁字符（审计 C5）。
        'sentence_romaji': _clean_romaji(analysis['romaji']),
        'chunks': chunks,
    }


def iter_simple_sentences(lessons, covered):
    """逐个产出课文对白句：(课号, id, 来源标签, source_id, 句子)。

    id 规则：会话课文 l{课}_c{句号}；应用课文 l{课}_x{段号}_{段内对白序号}（段号从 0 起）。
    中文旁白（type == 'narration'）没有 jp_raw，跳过。
    """
    for les in lessons:
        n = les['number']
        if n not in covered:
            continue
        for i, s in enumerate(les.get('basicc') or [], start=1):
            if (s.get('jp_raw') or '').strip():
                yield n, 'l%d_c%d' % (n, i), '会话课文', 'basicc_%d' % i, s
        for si, sec in enumerate(les.get('context_sections') or []):
            j = 0
            for s in sec:
                if not (isinstance(s, dict) and s.get('type') == 'dialogue'):
                    continue
                j += 1
                if (s.get('jp_raw') or '').strip():
                    yield n, 'l%d_x%d_%d' % (n, si, j), '应用课文', 'context_%d_%d' % (si, j), s


# 已覆盖的课（引擎生成透视图的范围）。扩课就改这里，
# 但必须先给该课每一句补上手写认知心法与 SENTENCE_META，否则构建会直接报错。
# 第 9～12 课是形容词（い／な形容词的 です・でした・くない・かった 与比较表达），
# 第 13 课是数量词（时间段／基准 に）、第 14 课是て形（て／てから／てください／目的の に）。
# 第 15～19 课：ています（进行／结果状态）、ても いいです・ては いけません、
#            が 欲しい／たい、く／に なります・します、ない形系（ないでください／
#            なければなりません／なくてもいいです）。
# 第 20～24 课：こと 的名词化（ことができます／ことです）、前に／後で／ほうがいい、
#            たり 的列举、かどうか 与疑问词小句＋か、と 的引用、んです 的说明语气、简体形。
# 引擎侧的表：ADJ_I_TAILS／adj_form（形容词）、TE_TAILS／_te_stem_masu（て形）、
#            COUNTERS／counter_gloss（数量词）。
# 本文件侧的表：INNER_FORMS／NA_INNER_FORMS（活用尾）、FORM_NOUN_HEADS／FORM_NOUN_ZH
#            （形式名词）、RENTAI_ZH（连体词）、_TE_STATIVE_STEMS（ています 的两种读法）、
#            TIME_TOPICS（时间话题是状语还是主语）、FORM_LIT_TOKENS（直译行的形态标注）。
COVERED_LESSONS = range(1, 49)

def main():
    covered = COVERED_LESSONS
    simple_covered = SIMPLE_LESSONS
    if '--lessons' in sys.argv:
        spec = sys.argv[sys.argv.index('--lessons') + 1]
        if '-' in spec:
            a, b = spec.split('-')
            covered = range(int(a), int(b) + 1)
        else:
            covered = [int(x) for x in spec.split(',')]
    if '--no-simple' in sys.argv:
        simple_covered = []
    elif '--simple' in sys.argv:
        k = sys.argv.index('--simple')
        spec = sys.argv[k + 1] if k + 1 < len(sys.argv) else ''
        if '-' in spec:
            a, b = spec.split('-')
            simple_covered = range(int(a), int(b) + 1)
        elif spec:
            simple_covered = [int(x) for x in spec.split(',')]
    with io.open(LESSONS_PATH, encoding='utf-8') as f:
        lessons = json.load(f)

    existing = []
    if os.path.exists(EXEMPLARS_PATH):
        with io.open(EXEMPLARS_PATH, encoding='utf-8') as f:
            existing = json.load(f)
    preserved = [apply_legacy_fixup(
                     localize_showcase(e) if e['id'] == 'screenshot_showcase' else e)
                 for e in existing if e['id'] in PRESERVE_IDS]

    generated = []
    for les in lessons:
        n = les['number']
        if n not in covered:
            continue
        title = les.get('title_clean', '')
        for i, b4 in enumerate(les.get('basic4') or [], start=1):
            sid = 'l%d_b%d' % (n, i)
            generated.append(build_exemplar(n, sid, b4, title))

    simple = []
    simple_ids = set()          # 本轮"尝试产出"的 id：整行汉语被跳过的那些也要算已覆盖
    for n, sid, label, src, item in iter_simple_sentences(lessons, simple_covered):
        simple_ids.add(sid)
        ex = build_simple_exemplar(n, sid, label, src, item)
        if ex is not None:
            simple.append(ex)

    # 未被本轮覆盖、也不在保留名单里的旧条目一并保留，避免误删后续课程的人工成果。
    # 简单图条目也算"已覆盖"——否则上一轮生成的课文条目会被当成旧条目，重复保留一份。
    covered_ids = ({e['id'] for e in generated} | simple_ids | PRESERVE_IDS)
    # 只保留**手写**的旧条目（人工成果）；引擎生成但已不在覆盖范围内的条目直接丢掉，
    # 否则把覆盖范围临时收窄（例如调试某几课）会留下一批"退不掉的"陈旧条目。
    others = [apply_legacy_fixup(localize_other(e))
              for e in existing
              if e['id'] not in covered_ids and not e.get('auto_generated')]

    out = preserved + others + generated + simple
    out.sort(key=lambda e: (e.get('lesson', 0), e['id']))

    with io.open(EXEMPLARS_PATH, 'w', encoding='utf-8') as f:
        json.dump(out, f, ensure_ascii=False, indent=2)

    # ---------------- 自检 ----------------
    problems = []
    for e in generated:
        if not e['chunks']:
            problems.append('%s: 没有 chunk' % e['id'])
        if e['id'] not in SENTENCE_META:
            problems.append('%s: 缺少手写 SENTENCE_META（标签／标题）' % e['id'])
        for c in e['chunks']:
            if c.get('particle') and not c.get('particle_color'):
                problems.append('%s: 助词 %s 缺颜色' % (e['id'], c['particle']))
            if c['text'] and not c.get('gloss_main'):
                problems.append('%s: %s 缺词义' % (e['id'], c['text']))
            if c['text'] and c.get('gloss_main') == c['text'] \
                    and re.search(r'(て|で|た|だ|り|ん|ば|ます|ない)$', c['text']):
                # 词义回落成词面：说明这个活用形没被识别（撮っても／忘れないで／来ると…）
                problems.append('%s: %s 的词义回落成词面（活用形未识别）' % (e['id'], c['text']))
            # 引号里的内容（「タバコを吸うな」）是被引用的整句，没有"词性/形态说明"可言
            if c['text'] and not c.get('gloss_sub') and not c['text'].startswith(('「', '『')):
                problems.append('%s: %s 缺形态说明（gloss_sub）' % (e['id'], c['text']))
            if not c.get('romaji'):
                problems.append('%s: %s 缺罗马音' % (e['id'], c['text']))
        ids = [c['id'] for c in e['chunks']]
        if e.get('zero_subject'):
            for t in e['zero_subject']['targets']:
                if t['id'] not in ids:
                    problems.append('%s: Ø が 箭头指向不存在的 chunk %s' % (e['id'], t['id']))
        for cl in e['literal_structure']:
            if not cl['tokens']:
                problems.append('%s: 第%d小句直译行为空' % (e['id'], cl['clause']))
            for t in cl['tokens']:
                if t.get('target_chunk') and t['target_chunk'] not in ids:
                    problems.append('%s: 直译 token 指向不存在的 chunk %s' % (e['id'], t['target_chunk']))

    # 简单图的自检：只查"看得见的东西"是否齐全，以及不许混进词义／直译／心法
    for e in simple:
        if not e['chunks']:
            problems.append('%s: 没有 chunk' % e['id'])
        for c in e['chunks']:
            if c.get('particle') and not c.get('particle_color'):
                problems.append('%s: 助词 %s 缺颜色' % (e['id'], c['particle']))
            if not c.get('romaji'):
                problems.append('%s: %s 缺罗马音' % (e['id'], c.get('text')))
            if 'gloss_main' in c or 'gloss_sub' in c:
                problems.append('%s: 简单图不该带词义字段' % e['id'])
        if e.get('literal_structure') or e.get('cognitive_note') or e.get('zero_subject'):
            problems.append('%s: 简单图不该带直译行／心法／零主语' % e['id'])

    print('已生成 %s' % EXEMPLARS_PATH)
    print('  保留手写条目 : %d' % len(preserved))
    print('  基本课文条目 : %d（覆盖第 %s 课）'
          % (len(generated), ','.join(str(x) for x in covered)))
    if simple:
        print('  课文简单条目 : %d（覆盖第 %s 课：会话课文＋应用课文）'
              % (len(simple), ','.join(str(x) for x in simple_covered)))
    print('  其他旧条目   : %d' % len(others))
    print('  合计         : %d' % len(out))
    zero_cnt = sum(1 for e in generated if e.get('zero_subject'))
    print('  含零主语推理 : %d / %d' % (zero_cnt, len(generated)))
    if problems:
        print('\n!! 自检发现 %d 个问题：' % len(problems))
        for p in problems:
            print('   -', p)
        raise SystemExit(1)
    print('  自检         : 通过（chunk/助词色/词义/罗马音/箭头锚点/直译行 全项）')


if __name__ == '__main__':
    main()
